<?php
require __DIR__.'/bootstrap.php';auth();require __DIR__.'/layout.php';$pdo=db();$err='';
if($_SERVER['REQUEST_METHOD']==='POST')try{check_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);
 if($action==='delete'){ $pdo->prepare('DELETE FROM cg_expenses WHERE id=?')->execute([$id]);redirect(); }
 $name=trim((string)($_POST['name']??''));$date=(string)($_POST['event_date']??'');$type=trim((string)($_POST['event_type']??''));$amount=money($_POST['amount']??0);$memo=trim((string)($_POST['memo']??''));$phone=phone($_POST['phone']??'');
 if(!$name||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!$type||$amount<=0)throw new RuntimeException('필수 항목을 확인하세요.');
 $pdo->beginTransaction();$pid=0;
 if($id){$st=$pdo->prepare('SELECT person_id FROM cg_expenses WHERE id=?');$st->execute([$id]);$pid=(int)$st->fetchColumn();if(!$pid)throw new RuntimeException('수정 대상 없음');$pdo->prepare("UPDATE cg_people SET name=?,phone=CASE WHEN ?<>'' THEN ? ELSE phone END WHERE id=?")->execute([$name,$phone,$phone,$pid]);}
 else{$st=$pdo->prepare('SELECT id FROM cg_people WHERE name=? ORDER BY id LIMIT 1');$st->execute([$name]);$pid=(int)$st->fetchColumn();if(!$pid){$pdo->prepare('INSERT INTO cg_people(name,phone) VALUES(?,?)')->execute([$name,$phone?:null]);$pid=(int)$pdo->lastInsertId();}elseif($phone){$pdo->prepare('UPDATE cg_people SET phone=? WHERE id=?')->execute([$phone,$pid]);}}
 if($id)$pdo->prepare('UPDATE cg_expenses SET event_date=?,event_type=?,amount=?,memo=? WHERE id=?')->execute([$date,$type,$amount,$memo,$id]);else $pdo->prepare('INSERT INTO cg_expenses(person_id,event_date,event_type,amount,memo) VALUES(?,?,?,?,?)')->execute([$pid,$date,$type,$amount,$memo]);$pdo->commit();redirect();
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
$q=trim((string)($_GET['q']??''));$year=(string)($_GET['year']??'');$args=[];$where=[];if($q!==''){$where[]='(p.name LIKE ? OR e.event_type LIKE ? OR e.memo LIKE ?)';$args=array_merge($args,array_fill(0,3,'%'.$q.'%'));}if(preg_match('/^\d{4}$/',$year)){$where[]='YEAR(e.event_date)=?';$args[]=$year;}$filter=$where?' WHERE '.implode(' AND ',$where):'';
$st=$pdo->prepare('SELECT COUNT(*) cnt,COALESCE(SUM(e.amount),0) total,COUNT(DISTINCT e.person_id) people FROM cg_expenses e JOIN cg_people p ON p.id=e.person_id'.$filter);$st->execute($args);$stats=$st->fetch();$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*30;$st=$pdo->prepare('SELECT e.*,p.name,p.phone FROM cg_expenses e JOIN cg_people p ON p.id=e.person_id'.$filter.' ORDER BY e.event_date DESC,e.id DESC LIMIT 30 OFFSET '.$offset);$st->execute($args);$rows=$st->fetchAll();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT e.*,p.name,p.phone FROM cg_expenses e JOIN cg_people p ON p.id=e.person_id WHERE e.id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
top('경조금 지출 관리');if($err)echo '<div class="alert alert-danger">'.h($err).'</div>';
?><div class="row g-3 mb-4"><div class="col-md-4"><div class="card p-3"><small>지출 건수</small><h2><?=number_format($stats['cnt'])?>건</h2></div></div><div class="col-md-4"><div class="card p-3"><small>지출 합계</small><h2><?=number_format($stats['total'])?>만원</h2></div></div><div class="col-md-4"><div class="card p-3"><small>대상자 수</small><h2><?=number_format($stats['people'])?>명</h2></div></div></div>
<div class="card p-4 mb-4"><h5><?=$edit?'내역 수정':'새 경조금 등록'?></h5><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div class="col-md-3"><label>이름 *</label><input class="form-control" name="name" value="<?=h($edit['name']??'')?>" required></div><div class="col-md-3"><label>경조일자 *</label><input type="date" class="form-control" name="event_date" value="<?=h($edit['event_date']??date('Y-m-d'))?>" required></div><div class="col-md-3"><label>경조대상 *</label><input class="form-control" name="event_type" placeholder="자녀결혼, 부, 모 등" value="<?=h($edit['event_type']??'')?>" required></div><div class="col-md-3"><label>지출금액(만원) *</label><input type="number" min="1" class="form-control" name="amount" value="<?=h($edit['amount']??'')?>" required></div><div class="col-md-4"><label>휴대전화번호</label><input class="form-control" name="phone" placeholder="01012345678" value="<?=h($edit['phone']??'')?>"></div><div class="col-md-8"><label>비고</label><input class="form-control" name="memo" value="<?=h($edit['memo']??'')?>"></div><div class="col-12"><button class="btn btn-primary">저장</button><?php if($edit):?><a class="btn btn-outline-secondary" href="index.php">취소</a><?php endif;?></div></form></div>
<div class="card p-3"><form class="row g-2 mb-3"><div class="col-md-6"><input class="form-control" name="q" placeholder="이름, 경조유형, 비고 검색" value="<?=h($q)?>"></div><div class="col-md-3"><input class="form-control" name="year" placeholder="연도 (예: 2026)" value="<?=h($year)?>"></div><div class="col-md-3"><button class="btn btn-outline-primary">검색</button> <a href="index.php" class="btn btn-outline-secondary">초기화</a></div></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th>일자</th><th>이름</th><th>경조대상</th><th class="text-end">지출액(만원)</th><th>비고</th><th>관리</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['event_date'])?></td><td><?=h($r['name'])?></td><td><?=h($r['event_type'])?></td><td class="text-end"><?=number_format($r['amount'])?></td><td><?=h($r['memo'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">수정</a><form method="post" class="d-inline" onsubmit="return confirm('삭제하시겠습니까?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">삭제</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-secondary <?=($page<=1?'disabled':'')?>" href="?<?=h(http_build_query(['q'=>$q,'year'=>$year,'page'=>$page-1]))?>">이전</a><span><?=$page?> / <?=max(1,ceil($stats['cnt']/30))?></span><a class="btn btn-sm btn-outline-secondary <?=($page*30 >= $stats['cnt']?'disabled':'')?>" href="?<?=h(http_build_query(['q'=>$q,'year'=>$year,'page'=>$page+1]))?>">다음</a></div></div><?php bottom(); ?>
